# (1) def, with if, elif and else
def average(nums):
    return sum(nums) / len(nums)


def label(score):
    if score >= 8:
        return "high"
    elif score >= 4:
        return "mid"
    else:
        return "low"


# (4) list methods
words = ["pear", "fig", "apple"]
words.append("kiwi")
words.sort()
last = words.pop()
print(words, last, len(words))

# (5) dict methods, and (2) for
lengths = {}
for w in words:
    lengths[w] = len(w)
for key, value in lengths.items():
    # (3) f-string
    print(f"{key} has {value} letters")
print(lengths.get("plum", 0), "fig" in lengths)

# (6) comprehensions
squares = [n * n for n in range(4)]
long_words = [w for w in words if len(w) > 3]
sizes = {w: len(w) for w in words}
print(squares, long_words, sizes)


# (8) class and __init__
class Counter:
    def __init__(self, name):
        self.name = name
        self.total = 0

    def add(self, amount):
        self.total += amount


c = Counter("steps")
c.add(5)
c.add(7)
print(f"{c.name}: {c.total}, average {average([c.total, 8]):.1f}, {label(c.total)}")

# (7) try and except
try:
    n = int("12a")
except ValueError:
    n = -1
print(n)

